   380  static void mg_mqtt_sub_unsub(struct mg_connection *c,
   381                                const struct mg_mqtt_opts *opts, uint8_t cmd) {
   382    uint8_t qos_ = opts->qos & 3;
   383    bool is_sub = cmd == MQTT_CMD_SUBSCRIBE;
   384    size_t plen = c->is_mqtt5 ? get_props_size(opts->props, opts->num_props) : 0;
   385    size_t len = 2 + opts->topic.len + 2 + (is_sub ? 1 : 0) + plen;
   386
   387    if (!mqtt_send_header(c, cmd, 2, (uint32_t) len)) goto fail;
   388    if (++c->mgr->mqtt_id == 0) ++c->mgr->mqtt_id;
   389    if (!mg_send_u16(c, mg_htons(c->mgr->mqtt_id))) goto fail;
   390
   391    if (c->is_mqtt5 && !mg_send_mqtt_properties(c, opts->props, opts->num_props))
   392      goto fail;
   393
   394    if (!mg_send_u16(c, mg_htons((uint16_t) opts->topic.len)) ||
   395        !mg_send(c, opts->topic.buf, opts->topic.len))
   396      goto fail;
   397    if (is_sub && !mg_send(c, &qos_, sizeof(qos_))) goto fail;
   398    return;
   399  fail:
   400    mg_error(c, "OOM");
   401  }
